syntax = "proto3";
package user.v1;

import "google/protobuf/wrappers.proto";

message GetUserRequest {
  int64 id = 1;                 // field 1-15 的 key 只占 1 字节，留给高频字段
  reserved 2, 3;                // 已删除字段的 tag 必须 reserved，防止复用
  reserved "deprecated_name";   // 字段名也要 reserved，防止 JSON/反射语义复用
}

message User {
  int64 id = 1;
  string name = 2;
  repeated string roles = 3;    // string repeated 是多段 length-delimited，不是 packed
  optional int32 score = 4;     // proto3 optional 生成 has_score，区分"未传"和"显式 0"
  google.protobuf.Int32Value age = 5; // wrapper 类型也能区分未设置和默认值
  repeated int64 role_ids = 6;  // 数值 repeated 在 proto3 默认 packed（wire_type=2）
}

service UserService {
  rpc GetUser(GetUserRequest) returns (User);                 // Unary: 1 请求 → 1 响应
  rpc WatchUsers(GetUserRequest) returns (stream User);       // Server streaming: 1 → N
  rpc ImportUsers(stream User) returns (GetUserRequest);      // Client streaming: N → 1
  rpc Chat(stream User) returns (stream User);                // Bidirectional: N ↔ N
}
